#!/usr/bin/env python3
"""Integrate measured supplemental results into the current bilingual paper."""
import hashlib,json,re,shutil
from pathlib import Path
REPO=Path(__file__).resolve().parents[1];ROOT=REPO/'reports/nns_vit_endpoint_supplement_v1_20260920';PAPER=REPO/'papers/nns_vit_endpoint/publication_r2_20260920';DEST=PAPER/'evidence/supplement_v1'
def load(n):return json.loads((ROOT/n).read_text())
def fmt(x):return 'NA' if x is None else f'{x:.4f}'
def ci(x):return 'NA' if x is None else '['+', '.join(fmt(v) for v in x)+']'
def mdtable(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(map(str,r))+' |' for r in rows]])
labels={'vit_b16':'ViT-B/16','deit_s16':'DeiT-S/16'};refs={'normalized_zero':'normalized-zero','blur_rgb':'blur'}
base=load('baseline_analysis.json');train=load('training_analysis.json');target=load('target_analysis.json');feature=load('feature_analysis.json');sampling=load('sampling_analysis.json');m2=load('m2_inherited.json')
DEST.mkdir(parents=True,exist_ok=True)
for n in ('baseline_analysis.json','baseline_image_values.csv','baseline_repeat_cohort_values.csv','baseline_repeat_image_values.csv','training_analysis.json','training_image_trends.csv','training_m3_block_values.csv','training_m4_block_values.csv','target_analysis.json','target_block_values.csv','feature_analysis.json','feature_unit_values.csv','feature_block_image_values.csv','sampling_analysis.json','m2_inherited.json','freeze.json','source_bindings.json','analysis_sources.json','acquisition_receipt.json','test_results.json','validation_report.json','paper_validation_summary.json','native_verification.json','independent_statistics_verification.json','figure_manifest.json','visual_inspection.json'):
 shutil.copy2(ROOT/n,DEST/n)
figmanifest=load('figure_manifest.json')
for r in figmanifest['figures']:
 for ext,f in r['files'].items():
  source=ROOT/f['path'];out=DEST/source.name;shutil.copy2(source,out)
shutil.copy2(REPO/'补充实验/执行协议v1.md',DEST/'protocol.md')
# Capture the exact manuscript state before changing its current numbers.
archive=ROOT/'pre_supplement_paper';archive.mkdir(exist_ok=True)
for lang in ('zh','en'):
 for name in ('manuscript.md','supplement.md'):
  p=PAPER/lang/name;backup=archive/f'{lang}_{name}'
  if not backup.exists():shutil.copy2(p,backup)
# Build shared numerical tables.
base_table=mdtable(['Model','Reference','Legacy random median','Corrected random mean','Corrected random median','Endpoint - random median [95% CI]','Taylor - random median [95% CI]'],[[labels[r['model']],refs[r['reference']],fmt(r['random_legacy']['median']),fmt(r['random_corrected']['mean']),fmt(r['random_corrected']['median']),fmt(r['endpoint_minus_random']['median'])+' '+ci(r['endpoint_minus_random']['median_ci95']),fmt(r['taylor_minus_random']['median'])+' '+ci(r['taylor_minus_random']['median_ci95'])] for r in base['summary']])
stability_table=mdtable(['Model','Reference','Median relative MC SE','q90 relative MC SE','MC image error R=5','R=10','R=20'],[[labels[r['model']],refs[r['reference']],fmt(r['relative_mc_se_median']),fmt(r['relative_mc_se_q90']),*[fmt(r['resampling'][str(k)]['median_image_absolute_mc_error']) for k in (5,10,20)]] for r in base['repeat_stability']])
train_table=mdtable(['Model','Study','Metric','Trained late - early','Random late - early','Trained - random [95% CI]','Random seed 1 / 2 / 3'],[[labels[r['model']],r['study'],r['metric'],fmt(r['trained_mean']),fmt(r['random_mean']),fmt(r['trained_minus_random'])+' '+ci(r['ci95']),' / '.join(fmt(v) for v in r['random_seed_means'])] for r in train['comparisons'] if r['quantity']=='late_minus_early'])
target_table=mdtable(['Model','Subset','Target','Metric','n','B11 - B0 mean','95% CI'],[[labels[r['model']],r['subset'],r['target'],r['metric'],r['n'],fmt(r['mean']),ci(r['ci95'])] for r in target['summary'] if r['quantity']=='late_minus_early'])
feature_table=mdtable(['Model','Pairing','Metric','Mean','95% CI'],[[labels[r['model']],r['control'],r['metric'],fmt(r['mean']),ci(r['ci95'])] for r in feature['summary'] if r['phase']=='all'])
feature_delta=mdtable(['Model','Control','Metric','Paired similarity advantage','95% CI'],[[labels[r['model']],r['control'],r['metric'],fmt(r['mean']),ci(r['ci95'])] for r in feature['contrasts'] if r['phase']=='all'])
sampling_table=mdtable(['Model','Metric','Reference mean','Image CI','Channel bootstrap range','Token bootstrap range','Leave-one-block range','Leave-one-stratum range'],[[labels[r['model']],r['metric'],fmt(r['reference']['mean']),ci(r['reference']['ci95']),ci(r['channel_bootstrap_mean_range']),ci(r['token_stratum_bootstrap_mean_range']),ci(r['leave_one_block_out_range']),ci(r['leave_one_stratum_out_range'])] for r in sampling['results']])
m2_table=mdtable(['Model','Reference','Block','Outcome','n images','Taylor > Endpoint Holm p','Supported'],[[labels[r['model']],refs[r['reference']],r['block'],r['outcome'],r['n_images'],f"{r['holm_p']:.4g}",r['reject']] for r in m2['tests']])
formula=r'''$$
\widehat A_{\rm random}=\frac1R\sum_{r=1}^R\frac1{0.25}\int_0^{0.25}|e_r(a)|\,da.
$$'''
feature_formula=r'''$$
s_{b,c}=\frac12\sum_{t=1}^{196}h_{b,t,c}^2,\qquad
q_t=\frac{h_{b,t,c}^2}{\sum_{j=1}^{196}h_{b,j,c}^2},\qquad
p_t=\frac{\sum_{i\in P_t}|x_i\partial s_{b,c}/\partial x_i|}{\sum_i|x_i\partial s_{b,c}/\partial x_i|}.
$$'''
texts={
'zh':dict(title='补充实验 v1：训练、目标和前向响应控制',intro='本补充完成建议文档第十一节的最低实验包与两项 P0 修正。新增结果为补充描述性分析；原确认性决策及封存证据保留。所有实验先冻结 cohort、通道、初始化种子和统计规则，再运行模型。',s9='随机区域基线修正',base='每个随机重复先对效应取绝对值并计算 AUC，再平均 20 次重复及图内 heads。旧估计器先平均 signed curves，因正负抵消低估 absolute-effect random baseline。下表比较 400 图 family 的图像级中位数及配对中位差；区间为 2,000 次图像 bootstrap。',base_end='修正后 ViT-B 两种 reference 的 Endpoint−random 中位差均为负；DeiT-S 的两个区间跨零。Taylor−random 四个区间均为正。Endpoint−Taylor 比较保持不变。',stability='每图随机均值的相对 MC 标准误中位数为 5.1%–6.9%，q90 为 7.6%–8.9%。从现有 20 次重复进行 5/10/20 次有放回重采样，误差随重复数减少而增大。固定图像下 cohort mean 的 Monte Carlo 误差小于图像抽样不确定性；单图细小优势仍不适合据此判定。该诊断只覆盖已观察的随机重复，不能证明任意精度下 20 次都足够。',s10='训练与随机初始化',training='ViT-B/16 和 DeiT-S/16 各使用 3 个随机初始化状态（202609201、202609202、202609203），与训练模型共享原 M3 cohort 的前 32 图、全部 12 blocks、16 tokens 和每层 16 个冻结 channels，M4 覆盖全部 heads。随机模型采用相同 timm 0.9.16 架构与默认初始化；同一状态用于全部图像。训练结果由同图、同目标的原始 M3/M4 数组筛选得到。图内先聚合，early=0–3、late=8–11；训练−随机区间同时重采样共享图像和模型种子（2,000 次），保留种子层级。',training_result='随机模型已出现 entropy 增大、locality 减小及距离增大，表明空间扩展有架构/初始化基础。训练模型的 entropy late−early 为 0.2288/0.2256，随机均值为 0.0940/0.1718；训练后的扩展更强。训练模型 routing scale 增大，而随机模型均值为负；attention identity 的层深趋势也在训练与随机状态间反向。MLP identity 两者均增加，ViT-B 的训练−随机差区间包含零。三个种子限制了对初始化总体的推断；此对照分离训练参数状态与原生初始化，未单独识别架构和初始化的贡献。',s11='目标稳健性',target='原 M3 冻结 100 图/模型，GT、clean-top1、top1−runnerup 三目标，blocks 0/5/11、全部 heads。分类索引固定于 clean 输入。正确/错误图分别为 ViT-B 92/8、DeiT-S 86/14；正确图的 GT 与 top1 完全一致。下表报告每图 head 聚合后的 B11−B0，并按 all/correct/incorrect 分组；所有目标在同一组使用相同 bootstrap 图像索引。',target_result='routing scale 和 Value-only error 在三种目标中均随深度增加；attention identity 减少，MLP identity 增加，正确与错误子集方向一致。Margin 改变幅度，例如 ViT-B routing 增量由 GT 的 0.2031 降至 0.1439，DeiT-S attention identity 降幅由 −0.2168 变为 −0.1014。两模型错误子集只有 8/14 图，其区间相应反映较少的图像信息。',jvp='native attention-output JVP 只依赖模型与输入，不依赖被解释的类别；其 8 方向 discrepancy 从原 M4 同图记录继承。target_contracted_jvp 另用每个目标对 head 输出的 cotangent 收缩方向导数，衡量目标相关 Value-only discrepancy。两者作为不同指标报告。Saturation relation 为图内同 block 跨 head 的 Spearman，并报告其层深变化；完整 block 值、目标配对差和 NA 数量见数据文件。',s12='Feature–Endpoint 定量关系',feature='每模型 32 张冻结图像，12 blocks × 16 个冻结随机 channels；共 12,288 个 energy targets。求和覆盖 196 个 patch tokens，排除 CLS，与原前向展示中的 energy 定义一致。Endpoint 使用原始 RGB absolute mass 后聚合到 patch，未用展示归一化或空间方差选通道。',feature_result='正确配对的图像级 Spearman 均值为 0.2663/0.2811；与同层错误 channel、跨层同 channel、patch 置换和随机 channel 四种控制的配对差区间均高于零。Cosine、Jensen–Shannon distance 和 top-20 overlap 也逐项报告。结果表明同通道的前向 energy 与局部输入依赖具有超出这些控制的关联，关联强度仍远低于等价。图内先取 channel、block 中位数，再在图像间统计。',s13='抽样敏感性',sampling='在相同 32 图上复用 M3 原 32 channels 和 15 patch strata。channel 与 token-stratum bootstrap 各 256 次，image bootstrap 2,000 次，并逐一移除 block 或空间 stratum。下表给出重采样分布和删除敏感性范围。前三个空间趋势方向在所有敏感性范围内保持一致。该分析没有生成独立 channel-seed 复现实验。CLS−patch 列为全层差值；其余为 late−early。',s14='跨层全-head M2 与适用范围',m2='主文 block-5 三-head 实验对应原确认性协议。已封存 M2 覆盖 blocks 2/5/10、两模型、全部 heads、两种 references、每 family 400 图；原生 patch 几何下完整输入替换 11/12、单-head 隔离替换 12/12 显著偏向 regional Taylor。下表使用原全部 672 个双向 AUC 检验的 Holm 校正，未重新定义检验 family。',optional='本轮未执行可选 cascading randomization、P2 同目标 M3–M4 桥接、独立 channel seeds、替代 checkpoint，或 P3 输入变换与 CNN 展示。本文不把训练对照解释为有限因果机制，也不把不同标量目标之间的总体关联解释为逐单元桥接。Path IG 的原冻结校准失败及原确认性结论保持不变。'),
'en':dict(title='Supplementary experiments v1: training, target and forward-response controls',intro='This supplement executes the minimum package in Section 11 of the experiment request and both P0 corrections. New estimates are supplementary descriptive analyses; original confirmatory decisions and sealed evidence are retained. Cohorts, channels, initialization seeds and estimators were fixed before model execution.',s9='Correction of the random-region baseline',base='Each random repetition takes the absolute effect before AUC integration; its AUC is then averaged over 20 repetitions and heads within an image. The legacy estimator averaged signed curves first and underestimated absolute-effect random performance through cancellation. The table reports medians and paired median differences for 400-image families, with 2,000 image-bootstrap intervals.',base_end='After correction, both ViT-B Endpoint-minus-random median differences are negative; both DeiT-S intervals include zero. All four Taylor-minus-random intervals remain positive. The Endpoint–Taylor comparison is unchanged.',stability='The median per-image relative Monte Carlo SE is 5.1%–6.9%, with q90 of 7.6%–8.9%. Resampling 5/10/20 repetitions from the observed pool shows increasing error at smaller repetition counts. Conditional on the fixed images, cohort-mean Monte Carlo variation is smaller than image-sampling uncertainty; small single-image advantages remain poorly resolved. This diagnostic covers the observed repetition pool and does not establish that 20 repetitions meet every precision requirement.',s10='Trained and randomly initialized models',training='Each ViT-B/16 and DeiT-S/16 architecture has three random states (202609201, 202609202, 202609203), sharing the first 32 frozen M3 images, all 12 blocks, 16 tokens and 16 frozen channels per block with the trained model; M4 includes all heads. Random states use the same timm 0.9.16 architecture and native initialization, and each state is fixed across images. Trained statistics are selected from existing M3/M4 raw arrays for the identical images and targets. Units are aggregated within images; early=0–3 and late=8–11. Trained-minus-random intervals independently resample shared images and initialization seeds in 2,000 crossed-bootstrap draws.',training_result='Random models already show increasing entropy and distance and decreasing locality, indicating an architectural/initialization basis for spatial broadening. Trained entropy late-minus-early is 0.2288/0.2256, compared with random means of 0.0940/0.1718. Training strengthens broadening. Routing scale increases in the trained models while its mean random trend is negative; attention identity also changes in opposite directions between trained and random states. MLP identity increases in both, with the ViT-B trained-minus-random interval including zero. Three seeds limit inference over the initialization population; the comparison separates trained parameter states from native initialization without isolating architecture from initialization.',s11='Target robustness',target='The frozen M3 cohort supplies 100 images per model, with GT, clean-top1 and top1-minus-runnerup targets at blocks 0/5/11 and all heads. Class indices are fixed on the clean input. Correct/incorrect counts are 92/8 for ViT-B and 86/14 for DeiT-S; GT and top1 are identical on correct images. The table reports image-level B11-minus-B0 after head aggregation for all/correct/incorrect groups. Targets within a group share bootstrap image indices.',target_result='Routing scale and Value-only error increase with depth under all three targets; attention identity decreases and MLP identity increases, with consistent directions in correct and incorrect subsets. Margin targets change magnitudes: ViT-B routing increases by 0.1439 rather than the GT value of 0.2031, and DeiT-S attention identity changes by −0.1014 rather than −0.2168. The incorrect subsets contain only 8/14 images, limiting their precision.',jvp='Native attention-output JVPs depend on the model and input, independently of the explained class, so their eight-direction discrepancy is inherited from the identical original M4 images. The additional target_contracted_jvp contracts directional derivatives with each target cotangent at the head output and measures target-dependent Value-only discrepancy. The two quantities are reported separately. Saturation relations use within-block Spearman across heads; their depth changes are reported alongside complete block values, target contrasts and NA counts in the data files.',s12='Quantitative feature–Endpoint relationship',feature='Each model uses 32 frozen images, 12 blocks and 16 frozen random channels per block, giving 12,288 energy targets. The sum covers 196 patch tokens and excludes CLS, matching the energy definition in the forward displays. Raw RGB Endpoint absolute mass is aggregated to patches; display normalization and spatial-variance channel selection do not enter the analysis.',feature_result='Mean image-level Spearman is 0.2663/0.2811 for correct pairing, with positive paired-difference intervals against wrong-channel, cross-layer same-channel, patch-permutation and random-channel controls. Cosine, Jensen–Shannon distance and top-20 overlap are also reported. Same-channel forward energy and local input dependence are associated beyond these controls, with substantial departures from equivalence. Channel and block medians are taken within each image before image-level statistics.',s13='Sampling sensitivity',sampling='The same 32 images reuse all original M3 32 channels and 15 patch strata. Channel and token-stratum bootstraps use 256 draws each, image bootstrap uses 2,000 draws, and each block or spatial stratum is omitted in turn. The table gives resampling and deletion-sensitivity ranges. The three spatial trend directions persist across all ranges. This resampling analysis does not constitute independent channel-seed replication. CLS-minus-patch is the all-layer difference; other metrics are late-minus-early.',s14='Cross-layer all-head M2 and scope',m2='The main block-5 three-head experiment corresponds to the original confirmatory protocol. Sealed M2 covers blocks 2/5/10, two models, all heads, two references and 400 images per family. Under native patch geometry, 11/12 full-input and 12/12 isolated-head families favor regional Taylor. The table retains Holm correction over the original 672 bidirectional AUC tests.',optional='Optional cascading randomization, the P2 same-target M3–M4 bridge, independent channel seeds and alternative checkpoints, and P3 input transforms and CNN display were not executed. Training controls concern local parameter-dependent structure; different scalar targets do not form a unit-matched finite causal mechanism. Original Path-IG calibration failure and confirmatory decisions are retained.')}
for lang,v in texts.items():
 chunks=[f"# {v['title']}",v['intro'],f"## S9. {v['s9']}",v['base'],formula,base_table,v['base_end'],'![Supplement Figure 1](../evidence/supplement_v1/sup_01_random_correction.png)',v['stability'],stability_table,'[20-repeat cohort distribution](../evidence/supplement_v1/baseline_repeat_cohort_values.csv) · [Per-image repeats](../evidence/supplement_v1/baseline_repeat_image_values.csv) · [Paired image values, MC SE, split-half and leave-one-repeat-out](../evidence/supplement_v1/baseline_image_values.csv)',f"## S10. {v['s10']}",v['training'],v['training_result'],train_table,'![Supplement Figure 2](../evidence/supplement_v1/sup_02_m3_training.png)','![Supplement Figure 3](../evidence/supplement_v1/sup_03_m4_training.png)','[Early/late and difference estimates](../evidence/supplement_v1/training_analysis.json) · [Image values](../evidence/supplement_v1/training_image_trends.csv)',f"## S11. {v['s11']}",v['target'],v['target_result'],v['jvp'],'![Supplement Figure 4](../evidence/supplement_v1/sup_04_target_robustness.png)',target_table,'[All block estimates, paired contrasts and NA counts](../evidence/supplement_v1/target_analysis.json) · [Image-block values](../evidence/supplement_v1/target_block_values.csv)',f"## S12. {v['s12']}",v['feature'],feature_formula,v['feature_result'],'![Supplement Figure 5](../evidence/supplement_v1/sup_05_feature_relation.png)',feature_table,feature_delta,'[Unit metrics](../evidence/supplement_v1/feature_unit_values.csv) · [Image-block values](../evidence/supplement_v1/feature_block_image_values.csv)',f"## S13. {v['s13']}",v['sampling'],sampling_table,f"## S14. {v['s14']}",v['m2'],m2_table,v['optional'],'[Frozen protocol](../evidence/supplement_v1/protocol.md) · [Source bindings](../evidence/supplement_v1/source_bindings.json) · [Task acquisition](../evidence/supplement_v1/acquisition_receipt.json) · [Numerical validation](../evidence/supplement_v1/validation_report.json)']
 (PAPER/lang/'supplement_experiments_v1.md').write_text('\n\n'.join(chunks)+'\n')
# Update the current main tables, preserving original Endpoint/Taylor estimates.
for lang in ('zh','en'):
 path=PAPER/lang/'manuscript.md';s=(archive/f'{lang}_manuscript.md').read_text();lines=s.splitlines();table_number=None
 for i,line in enumerate(lines):
  m=re.match(r'\*\*Table (\d+)\.',line)
  if m:table_number=int(m.group(1))
  if line.startswith('| ViT-B/16 |') or line.startswith('| DeiT-S/16 |'):
   cells=[v.strip() for v in line.strip('|').split('|')]
   if table_number not in (5,6,7):continue
   row=next(r for r in base['summary'] if labels[r['model']]==cells[0] and refs[r['reference']]==cells[1])
   if table_number==5:cells[5]=fmt(row['endpoint_minus_random']['median'])
   elif table_number==6:cells[4]=fmt(row['random_corrected']['median'])
   else:cells[4]=fmt(row['random_regret']['median'])
   lines[i]='| '+' | '.join(cells)+' |'
 s='\n'.join(lines)+'\n'
 if lang=='zh':
  s=s.replace('随机基线先平均 20 条 signed effect 曲线，再取绝对值积分。','随机基线对每次重复先取 absolute effect 并积分，再平均 20 次 AUC；其估计器与确定性方法使用相同绝对值顺序。')
  s=s.replace('逐层可视化进一步展示学习图像与前向特征图的对应关系。','训练与三种随机初始化对照表明，空间扩展具有架构与初始化基础，并在训练模型中增强；三种类别/决策目标保留主要趋势方向。冻结随机通道的定量分析显示，学习图像与前向 energy 的关联高于四种配对控制。')
  extra='''### 5.6 训练与初始化对照

在每模型 32 张共享图像、全部 12 blocks 和 3 个随机初始化状态上，随机模型也表现出空间扩展。训练模型 entropy 的 late−early 为 0.2288/0.2256，随机均值为 0.0940/0.1718；训练−随机差分别为 0.1348 [0.1232, 0.1466] 和 0.0539 [0.0473, 0.0602]。区间同时重采样模型种子和共享图像。Routing scale 的 trained/random 层深变化为 0.0512/−0.0479 与 0.1314/−0.0043；attention identity 在训练模型中减少、随机模型中增加。MLP identity 在两类状态中均增加，ViT-B 的增量差区间跨零。空间扩展存在架构/初始化基础，而训练后参数强化其幅度，并改变部分路径趋势。

### 5.7 目标稳健性

在每模型 100 张冻结图像的 blocks 0、5、11 上，GT、clean-top1 与 top1 margin 均保留 routing/Value-only error 增加、attention identity 减少和 MLP identity 增加的方向。ViT-B 与 DeiT-S 的正确/错误图数量为 92/8 和 86/14，两个子集分别报告。Margin 改变效应幅度，例如 ViT-B routing 的 B11−B0 从 GT 的 0.2031 变为 0.1439。Native attention-output JVP 不依赖类别目标；另外报告目标 cotangent 收缩的方向 discrepancy。

### 5.8 前向 feature 与 Endpoint 的定量关联

在每模型 32 图、12 blocks、每层 16 个冻结随机 channels 上，12,288 个 patch-energy 目标给出前向平方响应分布与 Endpoint absolute patch mass。正确配对的图像级 Spearman 均值为 0.2663/0.2811，均高于同层错误 channel、跨层同 channel、空间置换和随机 channel 控制；其配对差区间均为正。Cosine、Jensen–Shannon distance 和 top-20 overlap 得到对应的定量比较。前向响应与局部输入依赖具有同通道关联，仍为互补对象。

### 5.9 抽样敏感性

复用相同 32 图的原 M3 单元记录，channel/token-stratum/image bootstrap 以及 leave-one-block/stratum-out 均保留 entropy 增大、locality 减小与距离增大的方向。该结果描述既有样本的抽样敏感性。全部实验设置、逐项指标、区间及五张补充图见[补充实验 v1](supplement_experiments_v1.md)。

'''
  s=s.replace('## 6. 讨论',extra+'## 6. 讨论')
